-- Тема 19: варианты ответов выровнены по длине и форме (66 исправлений в 19 вопросах), ключи не меняются.
-- Источник: scripts/questions/090_option_length_topic19.js
-- Повторный запуск безопасен: вопрос и вариант ищутся по тексту, прежнее или уже новое значение допустимо,
-- иначе пакет отменяется. Ключи ответов, число и порядок вариантов не меняются.

BEGIN;
SET LOCAL standard_conforming_strings = on;
LOCK TABLE questions IN SHARE ROW EXCLUSIVE MODE;

DO $fix$
DECLARE fix record; matches integer; qid integer; k text;
BEGIN
    FOR fix IN SELECT * FROM (VALUES
        ('option', 'Что произойдёт при запуске этой программы обычным пользователем на Linux x86-64?
```
int main(void)
{
    __asm__ volatile("hlt");
    return 0;
}
```', 'Программа не скомпилируется', 'Компилятор отклонит привилегированную инструкцию', 'Компилятор вставит инструкцию: запрет проверяет процессор во время выполнения.', 'Компилятор вставит инструкцию без возражений: запрет проверяет процессор во время выполнения.'),
        ('option', 'Что произойдёт при запуске этой программы обычным пользователем на Linux x86-64?
```
int main(void)
{
    __asm__ volatile("hlt");
    return 0;
}
```', 'Процессор не выполнит инструкцию, ядро завершит процесс сигналом SIGSEGV', 'Ядро завершит процесс сигналом SIGSEGV', 'Привилегированная инструкция в кольце 3 вызывает ошибку защиты, её обрабатывает ядро.', 'Привилегированная инструкция в кольце 3 вызывает ошибку защиты: процессор её не выполняет, а ядро завершает процесс сигналом SIGSEGV.'),
        ('option', 'Зачем ядру нужно регулярное прерывание от таймера?', 'Чтобы регулярно получать управление и отдавать процессор другим задачам, даже если программа не делает системных вызовов', 'Чтобы регулярно получать управление над процессором', 'Так работает вытесняющая многозадачность: зависшая программа не захватит процессор навсегда.', 'Так работает вытесняющая многозадачность: ядро отдаёт процессор другим задачам, даже если программа не делает системных вызовов, и зависшая программа не захватит его навсегда.'),
        ('option', 'Зачем ядру нужно регулярное прерывание от таймера?', 'Чтобы синхронизировать системные часы по сети', 'Чтобы по сети синхронизировать системные часы сервера', NULL, NULL),
        ('option', 'Программа получила новую анонимную область памяти через mmap и впервые записывает в одну из её страниц. Что верно?', 'Ядро выделяет физическую страницу и повторяет инструкцию, программа этого не замечает', 'Ядро выделяет страницу и повторяет инструкцию', 'Так работает выделение памяти по требованию.', 'Так работает выделение памяти по требованию: ядро выделяет физическую страницу и повторяет инструкцию, а программа этого не замечает.'),
        ('option', 'Программа получила новую анонимную область памяти через mmap и впервые записывает в одну из её страниц. Что верно?', 'Ядро читает страницу из свопа', 'Ядро читает страницу из файла подкачки на диске', NULL, NULL),
        ('option', 'Программа получила новую анонимную область памяти через mmap и впервые записывает в одну из её страниц. Что верно?', 'Процесс получает сигнал SIGSEGV', 'Процесс получает сигнал SIGSEGV из-за доступа вне области', NULL, NULL),
        ('option', 'Что такое системный вызов?', 'Сигнал, который ядро посылает программе', 'Сигнал, который ядро посылает программе при ошибке', NULL, NULL),
        ('option', 'Что такое системный вызов?', 'Обращение программы к ядру с просьбой выполнить действие, которое ей запрещено в пользовательском режиме', 'Обращение программы к ядру за запрещённым ей действием', 'Например, записать файл, получить память или создать процесс.', 'Программа просит ядро выполнить действие, которое ей запрещено в пользовательском режиме. Например, записать файл, получить память или создать процесс.'),
        ('option', 'Что такое системный вызов?', 'Команда оболочки, например ls или cat', 'Команда оболочки, например ls или cat, запускающая программу', NULL, NULL),
        ('option', 'Что такое системный вызов?', 'Вызов любой функции из стандартной библиотеки C', 'Вызов любой функции из стандартной библиотеки языка C', NULL, NULL),
        ('option', 'Что верно для функции write() в программе на C?', 'printf вызывает её при каждом обращении', 'printf вызывает её сразу при каждом обращении к нему', NULL, NULL),
        ('option', 'Что верно для функции write() в программе на C?', 'Ошибку ядра она возвращает как -1, а код ошибки кладёт в errno', 'При ошибке возвращает -1 и кладёт код в errno', 'Ядро возвращает отрицательный код, обёртка переводит его в привычный для C вид.', 'Ядро возвращает отрицательный код, а обёртка переводит его в привычный для C вид: -1 и код ошибки в errno.'),
        ('option', 'Что верно для функции write() в программе на C?', 'Это обёртка из libc: она раскладывает параметры и выполняет инструкцию перехода в ядро', 'Это обёртка из libc, выполняющая переход в ядро', 'Саму запись выполняет ядро.', 'Обёртка раскладывает параметры по регистрам и выполняет инструкцию syscall; саму запись выполняет ядро.'),
        ('option', 'Что верно для функции write() в программе на C?', 'Сама функция write выполняется в режиме ядра', 'Вся функция write выполняется в режиме ядра', NULL, NULL),
        ('option', 'Программа вызывает функции open() и fork(), а в выводе strace видны openat и clone. Почему?', 'strace переименовывает вызовы для краткости', 'strace подставляет другие имена вызовов для краткости', NULL, NULL),
        ('option', 'Программа вызывает функции open() и fork(), а в выводе strace видны openat и clone. Почему?', 'Функции glibc open() и fork() выполняют системные вызовы openat и clone', 'Обёртки glibc open() и fork() вызывают openat и clone', 'Имена обёрток и вызовов ядра совпадают не всегда.', 'Функции glibc open() и fork() выполняют системные вызовы openat и clone. Имена обёрток и вызовов ядра совпадают не всегда.'),
        ('option', 'Программа вызывает функции open() и fork(), а в выводе strace видны openat и clone. Почему?', 'Это вызовы самой strace, а не программы', 'Это служебные вызовы самой strace, а не программы', NULL, NULL),
        ('option', 'Как на Linux x86-64 программа сообщает ядру, какой системный вызов нужен?', 'Передаёт имя вызова строкой', 'Передаёт ядру имя вызова текстовой строкой через стек', NULL, NULL),
        ('option', 'Как на Linux x86-64 программа сообщает ядру, какой системный вызов нужен?', 'Кладёт номер в переменную errno', 'Кладёт номер вызова в переменную errno и затем вызывает ядро', NULL, NULL),
        ('option', 'Как на Linux x86-64 программа сообщает ядру, какой системный вызов нужен?', 'Кладёт номер вызова в регистр rax и выполняет инструкцию syscall', 'Кладёт номер в регистр rax и выполняет инструкцию syscall', 'Параметры передаются в регистрах rdi, rsi, rdx, r10, r8 и r9, результат возвращается в rax.', 'Номер вызова кладут в rax, параметры передаются в регистрах rdi, rsi, rdx, r10, r8 и r9, результат возвращается в rax.'),
        ('option', 'Как на Linux x86-64 программа сообщает ядру, какой системный вызов нужен?', 'Записывает номер в файл /proc/self/syscall', 'Записывает номер вызова в файл /proc/self/syscall', NULL, NULL),
        ('option', 'Когда в программе на C имеет смысл читать errno?', 'Только после вызовов printf', 'Только после вызовов printf и других функций вывода', NULL, NULL),
        ('option', 'Когда в программе на C имеет смысл читать errno?', 'В любой момент: в errno хранится последняя ошибка всех процессов системы', 'В любой момент: errno хранит ошибки всех процессов', NULL, NULL),
        ('option', 'Когда в программе на C имеет смысл читать errno?', 'После того как функция сообщила об ошибке, например вернула -1', 'Только после сообщения функции об ошибке, например -1', 'errno объясняет причину уже случившейся ошибки.', 'errno объясняет причину уже случившейся ошибки; при успешном вызове его значение не определено.'),
        ('option', 'Что такое файловый дескриптор?', 'Полный путь к файлу', 'Полный путь к файлу, по которому его находит процесс', NULL, NULL),
        ('option', 'Что такое файловый дескриптор?', 'Номер файла внутри файловой системы (inode)', 'Номер файла на диске внутри файловой системы (inode)', NULL, NULL),
        ('option', 'Что такое файловый дескриптор?', 'Номер открытого файла, канала или сокета в таблице процесса; его возвращает open', 'Номер открытого файла или канала в таблице процесса', 'Дальше программа обращается к файлу по этому номеру.', 'Дальше программа обращается к файлу по этому номеру. Номер возвращает open, а открытым может быть файл, канал или сокет.'),
        ('option', 'Что такое файловый дескриптор?', 'Номер процесса, который открыл файл', 'Номер процесса, который открыл этот файл (PID)', NULL, NULL),
        ('option', 'Вызов write успешно записал все байты в обычный файл на диске; файл открыт без O_SYNC, O_DSYNC и O_DIRECT. Что верно?', 'Другие процессы уже могут прочитать эти данные из файла', 'Другие процессы уже могут прочитать эти данные', 'Чтение идёт через тот же кеш страниц.', 'Чтение идёт через тот же кеш страниц, поэтому другие процессы видят данные сразу.'),
        ('option', 'Вызов write успешно записал все байты в обычный файл на диске; файл открыт без O_SYNC, O_DSYNC и O_DIRECT. Что верно?', 'Сохранность данных при сбое питания или ОС не гарантирована', 'Сохранность при сбое питания или ОС не гарантирована', NULL, NULL),
        ('option', 'Вызов write успешно записал все байты в обычный файл на диске; файл открыт без O_SYNC, O_DSYNC и O_DIRECT. Что верно?', 'Данные гарантированно ещё не на диске', 'Данные гарантированно ещё не дошли до диска', NULL, NULL),
        ('option', 'Вызов write успешно записал все байты в обычный файл на диске; файл открыт без O_SYNC, O_DSYNC и O_DIRECT. Что верно?', 'Данные гарантированно уже записаны на диск', 'Данные гарантированно уже записаны на диск после write', NULL, NULL),
        ('option', 'Через какие системные вызовы malloc получает память у ядра в Linux?', '`shmget`', '`shmget` — создаёт сегмент общей памяти', NULL, NULL),
        ('option', 'Через какие системные вызовы malloc получает память у ядра в Linux?', '`fork`', '`fork` — создаёт копию процесса', NULL, NULL),
        ('option', 'Через какие системные вызовы malloc получает память у ядра в Linux?', '`mmap` — создаёт новую область адресов', '`mmap` — создаёт область адресов', NULL, NULL),
        ('option', 'Через какие системные вызовы malloc получает память у ядра в Linux?', '`read`', '`read` — читает данные из файла', NULL, NULL),
        ('option', 'Что не так в этом фрагменте?
