        ('option', 'Что не так в этом фрагменте?
```
write(fd, buf, len);
if (fdatasync(fd) == 0)
    printf("данные надёжно сохранены\n");
```', 'Не проверен результат write: он мог записать меньше len байт или вернуть ошибку, а fdatasync сохранит только записанное', 'Результат write не проверен: запись могла быть неполной', 'Успех fdatasync не исправляет ошибку предыдущей записи.', 'Не проверен результат write: он мог записать меньше len байт или вернуть ошибку, а fdatasync сохранит только записанное. Успех fdatasync не исправляет ошибку предыдущей записи.'),
        ('option', 'Программа напечатала через printf короткую строку без перевода строки; вся строка ещё лежит в буфере stdout и в файл не передана. Затем программа успешно вызвала fork. Вывод перенаправлен в файл, оба процесса завершились через exit. Что окажется в файле?', 'Строка дважды: буфер скопировался в ребёнка, и его сбросили оба процесса', 'Строка дважды: буфер скопировался в ребёнка при fork', NULL, NULL),
        ('option', 'Программа напечатала через printf короткую строку без перевода строки; вся строка ещё лежит в буфере stdout и в файл не передана. Затем программа успешно вызвала fork. Вывод перенаправлен в файл, оба процесса завершились через exit. Что окажется в файле?', 'Строка один раз', 'Строка один раз: родитель и ребёнок делят один буфер', 'Так было бы, если бы перед fork вызвали fflush(stdout).', 'Буфер при fork копируется, а не делится; один раз строка была бы, если бы перед fork вызвали fflush(stdout).'),
        ('option', 'Программа напечатала через printf короткую строку без перевода строки; вся строка ещё лежит в буфере stdout и в файл не передана. Затем программа успешно вызвала fork. Вывод перенаправлен в файл, оба процесса завершились через exit. Что окажется в файле?', 'Ничего не окажется', 'Ничего не окажется: exit не сбрасывает буферы stdio', NULL, NULL),
        ('option', 'Программа напечатала через printf короткую строку без перевода строки; вся строка ещё лежит в буфере stdout и в файл не передана. Затем программа успешно вызвала fork. Вывод перенаправлен в файл, оба процесса завершились через exit. Что окажется в файле?', 'Строка появится, только если вызвать fsync', 'Строка не появится без вызова fsync на файл', 'fsync отвечает за сброс на диск, а не за сброс буфера printf.', 'fsync отвечает за сброс на диск, а не за сброс буфера printf; строка попадёт в файл при exit.'),
        ('option', 'Что верно для системных вызовов fork и execve?', 'fork создаёт копию процесса: родителю возвращает номер ребёнка, ребёнку — 0', 'fork создаёт копию процесса, ребёнку возвращает 0', 'По результату fork процесс понимает, кто он.', 'Родителю fork возвращает номер ребёнка, ребёнку — 0: по результату процесс понимает, кто он.'),
        ('option', 'Что верно для системных вызовов fork и execve?', 'execve создаёт новый процесс', 'execve создаёт новый процесс с новым номером', NULL, NULL),
        ('option', 'Что верно для системных вызовов fork и execve?', 'execve заменяет программу в текущем процессе, номер процесса сохраняется', 'execve заменяет программу, номер процесса сохраняется', 'Прежние код и данные исчезают; открытые файлы остаются, кроме помеченных FD_CLOEXEC.', 'Заменяет программу в текущем процессе: прежние код и данные исчезают; открытые файлы остаются, кроме помеченных FD_CLOEXEC.'),
        ('option', 'Что верно для системных вызовов fork и execve?', 'fork сразу копирует всю память родителя', 'fork сразу копирует всю память родителя в ребёнка', NULL, NULL),
        ('option', 'Что верно для системных вызовов fork и execve?', 'PostgreSQL в Linux запускает каждый обслуживающий процесс через fork и затем execve', 'PostgreSQL в Linux запускает обслуживающий процесс через fork и execve', NULL, NULL),
        ('option', 'Что значит состояние Z у процесса в выводе ps?', 'Процесс выполняется в режиме ядра', 'Процесс сейчас выполняется в режиме ядра', NULL, NULL),
        ('option', 'Что значит состояние Z у процесса в выводе ps?', 'Процесс завершился, но родитель ещё не забрал его код завершения вызовом wait', 'Процесс завершился, родитель ещё не вызвал wait', 'Такой процесс называют зомби: память освобождена, осталась только запись о нём.', 'Процесс завершился, но родитель ещё не забрал его код завершения вызовом wait. Такой процесс называют зомби: память освобождена, осталась только запись о нём.'),
        ('option', 'Что значит состояние Z у процесса в выводе ps?', 'Процесс остановлен сигналом SIGSTOP', 'Процесс остановлен сигналом SIGSTOP и не работает', NULL, NULL),
        ('option', 'Как postmaster обслуживает новое подключение клиента в Linux?', 'Создаёт новый поток внутри своего процесса', 'Создаёт новый поток внутри процесса postmaster и передаёт ему соединение', NULL, NULL),
        ('option', 'Как postmaster обслуживает новое подключение клиента в Linux?', 'Запускает новую программу postgres вызовом execve', 'Запускает новую программу postgres вызовом execve для клиента', NULL, NULL),
        ('option', 'Как postmaster обслуживает новое подключение клиента в Linux?', 'Принимает его вызовом accept и создаёт обслуживающий процесс вызовом fork; ребёнок наследует дескриптор соединения', 'Принимает вызовом accept и создаёт процесс вызовом fork', 'Дальше с клиентом общается только ребёнок, а postmaster снова ждёт подключений.', 'Принимает подключение вызовом accept и создаёт обслуживающий процесс вызовом fork; ребёнок наследует дескриптор соединения. Дальше с клиентом общается только ребёнок, а postmaster снова ждёт подключений.'),
        ('option', 'Команда time показала: real 2.1s, user 0.4s, sys 1.6s. Что это значит?', 'Большую часть процессорного времени программа провела в режиме ядра, выполняющем для неё работу', 'Большую часть времени программа провела в режиме ядра', 'Обычно это признак множества системных вызовов или дорогих операций ядра.', 'Обычно это признак множества системных вызовов или дорогих операций ядра, выполняющих работу для программы.'),
        ('option', 'Команда time показала: real 2.1s, user 0.4s, sys 1.6s. Что это значит?', 'Программа 1.6 секунды ждала диска', 'Программа 1.6 секунды ждала ответа от диска, а не процессора', NULL, NULL),
        ('option', 'Команда time показала: real 2.1s, user 0.4s, sys 1.6s. Что это значит?', 'Программа работала в 1.6 потоках', 'Программа работала в 1.6 потоках на нескольких ядрах процессора', NULL, NULL),
        ('option', 'Что верно для утилиты strace?', 'Показывает только номера вызовов, без данных', 'Показывает номера вызовов без параметров и данных', NULL, NULL),
        ('option', 'Что верно для утилиты strace?', 'Безопасна для подключения к рабочему серверу PostgreSQL в часы нагрузки', 'Безопасна для рабочего сервера PostgreSQL в часы нагрузки', NULL, NULL),
        ('option', 'Что верно для утилиты strace?', 'Может вывести содержимое данных программы, в том числе пароли и тексты запросов', 'Может вывести данные программы, в том числе пароли и запросы', 'Поэтому необработанный вывод чужих программ не публикуют.', 'Содержимое данных, в том числе пароли и тексты запросов, попадает в вывод, поэтому необработанный вывод чужих программ не публикуют.'),
        ('option', 'Что верно для утилиты strace?', 'Показывает системные вызовы программы с параметрами и результатами', 'Показывает системные вызовы с параметрами и результатами', NULL, NULL),
        ('option', 'Что верно для утилиты strace?', 'Может существенно замедлить наблюдаемый процесс, особенно при частых системных вызовах', 'Может заметно замедлить наблюдаемый процесс', 'Каждый отслеживаемый вызов останавливает процесс, чтобы strace его записала; насколько это заметно, зависит от нагрузки.', 'Может существенно замедлить наблюдаемый процесс, особенно при частых системных вызовах: каждый отслеживаемый вызов останавливает процесс, чтобы strace его записала; насколько это заметно, зависит от нагрузки.'),
        ('option', 'В /proc/PID/syscall обслуживающего процесса PostgreSQL первое поле равно 232. Что это значит?', 'Процесс ждёт в системном вызове epoll_wait — обычно следующего запроса клиента', 'Процесс ждёт в системном вызове epoll_wait', '232 — номер epoll_wait на x86-64.', '232 — номер epoll_wait на x86-64; в этом вызове обслуживающий процесс обычно ждёт следующего запроса клиента.'),
        ('option', 'В /proc/PID/syscall обслуживающего процесса PostgreSQL первое поле равно 232. Что это значит?', 'Процесс получил 232 сигнала', 'Процесс получил 232 сигнала от клиента', NULL, NULL)
    ) AS fixes(kind, question_text, opt_text, new_opt_text, old_text, new_text)
    LOOP
        -- Сначала ровно один вопрос по тексту (прежнему или новому), дальше всё только по его id.
        SELECT count(*), min(id) INTO matches, qid FROM questions
        WHERE question_text IN (fix.question_text, CASE WHEN fix.kind = 'question' THEN fix.new_text ELSE fix.question_text END);
        IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вопрос для исправления'; END IF;
        IF fix.kind = 'question' THEN
            UPDATE questions SET question_text = fix.new_text WHERE id = qid;
        ELSIF fix.kind = 'explanation' THEN
            PERFORM 1 FROM questions WHERE id = qid AND explanation IN (fix.old_text, fix.new_text);
            IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение вопроса'; END IF;
            UPDATE questions SET explanation = fix.new_text WHERE id = qid;
        ELSE
            SELECT count(*), min(o.key) INTO matches, k
            FROM questions q, jsonb_each_text(q.options) o
            WHERE q.id = qid AND o.value IN (fix.opt_text, coalesce(fix.new_opt_text, fix.opt_text));
            IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вариант ответа для исправления'; END IF;
            IF fix.new_text IS NOT NULL THEN
                PERFORM 1 FROM questions WHERE id = qid AND option_notes ->> k IN (fix.old_text, fix.new_text);
                IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение варианта'; END IF;
                UPDATE questions SET option_notes = jsonb_set(option_notes, ARRAY[k], to_jsonb(fix.new_text)) WHERE id = qid;
            END IF;
            IF fix.new_opt_text IS NOT NULL THEN
                UPDATE questions SET options = jsonb_set(options, ARRAY[k], to_jsonb(fix.new_opt_text)) WHERE id = qid;
            END IF;
        END IF;
    END LOOP;
END
$fix$;

COMMIT;
